const query = $input.first().json.query || {};
const token = (query.token || '').trim();
const chain = (query.chain || 'solana').toLowerCase();

if (!token) {
  throw new Error('Missing ?token= parameter. Usage: ?token=<address>&chain=solana|base');
}

return [{
  json: {
    token,
    chain,
    isBase: chain === 'base',
    isSolana: chain === 'solana',
    goplusChain: chain === 'solana' ? 'solana' : '8453',
    birdeyeChain: chain === 'solana' ? 'solana' : 'base',
    timestamp: new Date().toISOString()
  }
}];

const input = $('Parse Input').first().json;
const dex = $('DexScreener Fetch').first().json;
const birdeyeOverview = $('Birdeye Overview').first().json;
const tradesRaw = $('Birdeye Trades').first().json;
const goplusRaw = $('GoPlus Security').first().json;
const rugRaw = $('RugCheck').first().json;
const honeypotRaw = $('Honeypot').first().json;

const { token, chain, isBase, isSolana } = input;

// DexScreener: pick best pair by liquidity
const pairs = dex.pairs || [];
const bestPair = pairs.slice().sort((a, b) => {
  const lA = (a.liquidity && a.liquidity.usd) || 0;
  const lB = (b.liquidity && b.liquidity.usd) || 0;
  return lB - lA;
})[0] || {};

const price = bestPair.priceUsd ? parseFloat(bestPair.priceUsd) : 0;
const liq   = (bestPair.liquidity && bestPair.liquidity.usd) || 0;
const mcap  = bestPair.fdv || 0;
const vol5m  = (bestPair.volume && bestPair.volume.m5)  || 0;
const vol1h  = (bestPair.volume && bestPair.volume.h1)  || 0;
const vol6h  = (bestPair.volume && bestPair.volume.h6)  || 0;
const vol24h = (bestPair.volume && bestPair.volume.h24) || 0;
const pc5m  = (bestPair.priceChange && bestPair.priceChange.m5)  || 0;
const pc1h  = (bestPair.priceChange && bestPair.priceChange.h1)  || 0;
const pc6h  = (bestPair.priceChange && bestPair.priceChange.h6)  || 0;
const pc24h = (bestPair.priceChange && bestPair.priceChange.h24) || 0;
const b5m = (bestPair.txns && bestPair.txns.m5 && bestPair.txns.m5.buys)  || 0;
const s5m = (bestPair.txns && bestPair.txns.m5 && bestPair.txns.m5.sells) || 0;
const b1h = (bestPair.txns && bestPair.txns.h1 && bestPair.txns.h1.buys)  || 0;
const s1h = (bestPair.txns && bestPair.txns.h1 && bestPair.txns.h1.sells) || 0;
const pairCreatedAt = bestPair.pairCreatedAt ? new Date(bestPair.pairCreatedAt) : null;
const ageMin = pairCreatedAt ? Math.floor((Date.now() - pairCreatedAt.getTime()) / 60000) : 0;
const tokenName   = (bestPair.baseToken && bestPair.baseToken.name)   || 'Unknown';
const tokenSymbol = (bestPair.baseToken && bestPair.baseToken.symbol) || '???';
const dexName     = bestPair.dexId || 'unknown';
const vlRatio    = liq > 0 ? (vol1h / liq) : 0;
const buyPct5m   = (b5m + s5m) > 0 ? Math.round(100 * b5m / (b5m + s5m)) : 0;
const buyPct1h   = (b1h + s1h) > 0 ? Math.round(100 * b1h / (b1h + s1h)) : 0;

// Birdeye overview
const bird = (birdeyeOverview && birdeyeOverview.data) || {};
const uniqueTraders = bird.uniqueWallet1h || bird.uniqueWallet24h || 'N/A';
const netFlow = bird.buy1hVolume && bird.sell1hVolume
  ? '$' + Math.round(bird.buy1hVolume - bird.sell1hVolume).toLocaleString()
  : 'N/A';

// Birdeye trades (free tier - may be empty/error)
const trades = (tradesRaw && tradesRaw.data && tradesRaw.data.items) || [];
const tradeLines = trades.slice(0, 15).map(t => {
  const side = (t.side || t.txType || '?').toUpperCase();
  const usd  = t.volumeInUsd ? '$' + parseFloat(t.volumeInUsd).toFixed(0) : 'N/A';
  const ts   = t.blockUnixTime ? new Date(t.blockUnixTime * 1000).toISOString().slice(11, 19) : '??:??:??';
  return `  ${side} ${usd} @ ${ts}`;
}).join('\n');

// GoPlus
const gpResult = goplusRaw && goplusRaw.result;
const gpToken  = gpResult && (gpResult[token.toLowerCase()] || gpResult[token]);
const honeypotFlag = gpToken ? (gpToken.is_honeypot === '1') : false;
const buyTax       = gpToken ? parseFloat(gpToken.buy_tax  || 0) : 0;
const sellTax      = gpToken ? parseFloat(gpToken.sell_tax || 0) : 0;
const isMintable   = gpToken ? (gpToken.is_mintable === '1') : false;
const isProxy      = gpToken ? (gpToken.is_proxy    === '1') : false;
const holderCount  = gpToken ? (gpToken.holder_count || 'N/A') : 'N/A';
const top10Pct     = gpToken ? (gpToken.top_10_holders || []).reduce((s, h) => s + parseFloat(h.percent || 0), 0) : 0;
const ownerRenounced = gpToken ? (gpToken.owner_address === '0x0000000000000000000000000000000000000000' || gpToken.owner_address === '') : null;

// RugCheck (Solana)
const rugScore = rugRaw && rugRaw.score_normalised !== undefined ? rugRaw.score_normalised : (rugRaw && rugRaw.score !== undefined ? rugRaw.score : null);
const rugRisks = (rugRaw && rugRaw.risks) || [];

// Honeypot.is (Base)
const hpResult = honeypotRaw && honeypotRaw.honeypotResult;
const hpFlag   = hpResult && hpResult.isHoneypot;

// Security summary
const secFlags = [];
if (honeypotFlag || hpFlag) secFlags.push('🔴 HONEYPOT DETECTED');
if (isMintable)             secFlags.push('🔴 Mintable: unlimited supply risk');
if (isProxy)                secFlags.push('🟡 Proxy contract (upgradeable)');
if (buyTax  > 5)            secFlags.push(`🟡 Buy tax: ${buyTax}%`);
if (sellTax > 5)            secFlags.push(`🔴 Sell tax: ${sellTax}%`);
if (top10Pct > 60)          secFlags.push(`🔴 Top-10 holders: ${top10Pct.toFixed(1)}% (very concentrated)`);
else if (top10Pct > 40)     secFlags.push(`🟡 Top-10 holders: ${top10Pct.toFixed(1)}% (concentrated)`);
rugRisks.forEach(r => {
  const icon = r.level === 'danger' ? '🔴' : '🟡';
  secFlags.push(`${icon} ${r.name}${r.description ? ': ' + r.description : ''}`);
});
if (secFlags.length === 0)  secFlags.push('✅ No critical security flags detected');

const age = ageMin >= 60 ? `${Math.floor(ageMin/60)}h ${ageMin%60}m` : `${ageMin}m`;
const fmtUsd = n => '$' + Math.round(n).toLocaleString();
const fmtPct = n => (n >= 0 ? '+' : '') + n.toFixed(2) + '%';

const system = `You are an expert crypto trader and analyst specializing in new token launches on decentralized exchanges. You provide deep conviction-level analysis for traders with a 5-15 minute decision window. Be direct, specific, and honest. Do not pad your response with generic disclaimers.`;

const user = `DEEP-DIVE TOKEN ANALYSIS

Token: ${tokenName} (${tokenSymbol})
Address: ${token}
Chain: ${chain.toUpperCase()} | DEX: ${dexName} | Age: ${age}
Requested: ${new Date().toISOString()}

=== MARKET DATA ===
Price:      $${price < 0.000001 ? price.toExponential(4) : price.toPrecision(6)}
Liquidity:  ${fmtUsd(liq)}
FDV:        ${fmtUsd(mcap)}
V/L Ratio:  ${vlRatio.toFixed(1)}x (1h vol / liq)

=== VOLUME ===
5m:  ${fmtUsd(vol5m)} | 1h: ${fmtUsd(vol1h)} | 6h: ${fmtUsd(vol6h)} | 24h: ${fmtUsd(vol24h)}

=== PRICE CHANGE ===
5m: ${fmtPct(pc5m)} | 1h: ${fmtPct(pc1h)} | 6h: ${fmtPct(pc6h)} | 24h: ${fmtPct(pc24h)}

=== BUY PRESSURE ===
5m:  ${buyPct5m}% buys  (${b5m} buys / ${s5m} sells)
1h:  ${buyPct1h}% buys  (${b1h} buys / ${s1h} sells)

=== ON-CHAIN ENRICHMENT (Birdeye) ===
Unique wallets (1h): ${uniqueTraders}
Net buy inflow (1h): ${netFlow}
${tradeLines ? `\nRecent trades:\n${tradeLines}` : '(Trade history unavailable on free tier)'}

=== SECURITY ANALYSIS ===
${secFlags.join('\n')}

GoPlus data:
  Holder count: ${holderCount}
  Top-10 concentration: ${top10Pct > 0 ? top10Pct.toFixed(1) + '%' : 'N/A'}
  Buy/sell tax: ${buyTax}% / ${sellTax}%
  Owner renounced: ${ownerRenounced === null ? 'N/A' : ownerRenounced ? 'Yes' : 'No'}
${isSolana && rugScore !== null ? `RugCheck risk score: ${rugScore}` : ''}
${isBase ? `Honeypot.is: ${hpFlag ? 'HONEYPOT' : 'Clear'}` : ''}

=== HISTORICAL CONTEXT ===
Our 1,447-signal dataset (May 3-14) shows:
- Base INTERESTING: avg +20.8% at 5m, +40.9% at 15m
- Solana INTERESTING: avg -3.2% at 5m, -17.1% at 15m
- V/L 0-4x: avg +10.1% at 5m (best bucket)
- V/L 8x+: net-negative at ALL horizons (filtered out in triage)
- Even best bucket turns negative at 30m -- these are 5m momentum events

=== ANALYSIS REQUESTED ===
Provide a structured deep-dive with these six sections:

1. VOLUME AUTHENTICITY
Is this organic accumulation (many independent buyers) or suspicious (wash trading, bot activity, symmetric buy/sell)? What does the buy/sell ratio tell you?

2. MOMENTUM QUALITY
Is buy pressure building, sustained, or decaying? How does the volume profile across timeframes tell a story?

3. SECURITY VERDICT
Walk through every flag above. Give an honest risk rating (LOW / MEDIUM / HIGH / CRITICAL) and explain the actual exposure.

4. CHAIN & PROFILE FIT
Given this is ${chain.toUpperCase()}: how does this token compare to what historically works in our dataset? Does it fit the profile of a 5m momentum winner?

5. CONVICTION VERDICT
State clearly: ENTER NOW / WAIT FOR DIP / PASS
If ENTER: specific entry price, target, stop-loss with percentages
If WAIT: what price or signal to wait for
If PASS: the specific reason

6. INVALIDATION SCENARIOS
What 2-3 specific price levels or pattern changes would immediately invalidate this thesis?

Be concrete. Reference the actual numbers above. No generic disclaimers.`;

