const formatBody = (text) => {
  const lines = text.split('\n');
  let html = '';
  let inList = false;
  for (const raw of lines) {
    const line = raw.trimEnd();
    if (!line) {
      if (inList) { html += '</ul>'; inList = false; }
      continue;
    }
    if (/^#{1,3}\s*\d+\./.test(line) || (/^\d+\.\s+[A-Z][A-Z ]{3,}/.test(line) && line.length < 80)) {
      if (inList) { html += '</ul>'; inList = false; }
      html += `<h3 class="section-title">${line}</h3>`;
    } else if (/^[-*]\s/.test(line)) {
      if (!inList) { html += '<ul>'; inList = true; }
      const inner = line.replace(/^[-*]\s/, '').replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
      html += `<li>${inner}</li>`;
    } else {
      if (inList) { html += '</ul>'; inList = false; }
      const fmtd = line.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
      html += `<p>${fmtd}</p>`;
    }
  }
  if (inList) html += '</ul>';
  return html;
};

